CREATE VIEW v65311 AS SELECT *, JSON_ARRAYAGG(x4.v64885) OVER (ORDER BY x5.v64603, x5.v64604 ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS x1, ST_EQUALS(ST_GEOMFROMTEXT('GEOMETRYCOLLECTION()'), ST_GEOMETRYFROMWKB(ST_ASWKB(ST_GEOMETRYFROMTEXT('POINT(1 4)')))) AS x2 FROM v64602 AS x5 RIGHT JOIN v64883 AS x4 ON x5.v64604 = x5.v64604 WHERE x5.v64603 <= 3